// Some portions generated by Codex
package org.eclipse.rdf4j.query;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.charset.StandardCharsets;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

class EncodedValueTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void reconstructsExactUnicodeTermsAndDatatypeLexicalForms() {
		String text = "NUL\u0000/é/e\u0301/漢字/😀";
		assertEquals(VF.createIRI("urn:namespace:", text),
				EncodedValue.iri(utf8("urn:namespace:"), utf8(text)).toValue(VF));
		assertEquals(VF.createBNode(text), EncodedValue.bnode(utf8(text)).toValue(VF));
		assertEquals(VF.createLiteral(text), EncodedValue.literal(utf8(text), CoreDatatype.XSD.STRING).toValue(VF));
		assertEquals(VF.createLiteral("+0001", CoreDatatype.XSD.INTEGER),
				EncodedValue.literal(utf8("+0001"), CoreDatatype.XSD.INTEGER).toValue(VF));
		assertEquals(VF.createLiteral(text, VF.createIRI("urn:datatype:custom")), EncodedValue
				.literal(utf8(text), EncodedValue.iri(utf8("urn:datatype:"), utf8("custom")))
				.toValue(VF));
	}

	@Test
	void languageAndDirectionRemainSeparateAndExact() {
		for (Literal.BaseDirection direction : Literal.BaseDirection.values()) {
			Literal expected = direction == Literal.BaseDirection.NONE ? VF.createLiteral("مرحبا", "ar")
					: VF.createLiteral("مرحبا", "ar", direction);
			assertEquals(expected, EncodedValue.languageLiteral(utf8("مرحبا"), utf8("ar"), direction).toValue(VF));
		}
	}

	@Test
	void cannotConstructIncompleteTypedDescriptors() {
		assertThrows(IllegalArgumentException.class, () -> EncodedValue.literal(utf8("x"), CoreDatatype.NONE));
		assertThrows(IllegalArgumentException.class,
				() -> EncodedValue.literal(utf8("x"), CoreDatatype.RDF.LANGSTRING));
		assertThrows(IllegalArgumentException.class,
				() -> EncodedValue.literal(utf8("x"), (CoreDatatype) () -> VF.createIRI("urn:custom:datatype")));
		assertThrows(IllegalArgumentException.class,
				() -> EncodedValue.literal(utf8("x"), EncodedValue.bnode(utf8("not-a-datatype"))));
	}

	private static byte[] utf8(String value) {
		return value.getBytes(StandardCharsets.UTF_8);
	}
}
